mapper.select:
select 'APPLICATION_SNAPSHOT' resourceType,a.id resourceId from p_application a where a.id=#{applicationId}
union all select 'AVATAR_VERSION',avatar.current_version_id from p_application a join p_avatar avatar on avatar.id=a.avatar_id where a.id=#{applicationId}
union all select 'VOICE_VERSION',voice.current_version_id from p_application a join p_voice voice on voice.id=a.voice_id where a.id=#{applicationId}
union all select 'VOICE_VERSION',v.fallback_voice_version_id from p_application a join p_voice voice on voice.id=a.voice_id join p_voice_version v on v.id=voice.current_version_id where a.id=#{applicationId} and v.fallback_voice_version_id is not null
union all select 'SKILL',skill_id from p_application_skill where application_id=#{applicationId}

select count(distinct holder_id) from p_resource_reference
    where account_id=#{accountId} and holder_type='SESSION' and holder_id!=#{sessionId}
      and resource_type='APPLICATION_SNAPSHOT' and state in ('RESERVED','CONFIRMED')

select count(*) from p_resource_reference
    where account_id=#{accountId} and holder_type='SESSION' and holder_id=#{sessionId}
      and operation_id=#{operationId} and state='CONFIRMED'
